// Junta agenda, clima e tarefas numa única mensagem (HTML do Telegram)
const zona = 'America/Sao_Paulo';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const eventos = ($('Agrupar eventos').first().json.eventos || [])
  .filter((e) => e.summary)
  .map((e) => ({
    titulo: e.summary,
    inicio: e.start?.dateTime ? DateTime.fromISO(e.start.dateTime).setZone(zona) : null,
    local: e.location,
  }))
  .sort((a, b) => (a.inicio?.toMillis() ?? 0) - (b.inicio?.toMillis() ?? 0));

const clima = $('Previsão do tempo').first().json;
const hoje = DateTime.now().setZone(zona).setLocale('pt-BR');
const hojeISO = hoje.toISODate();

// Tudo sobre o banco do Notion vem do nó "Configuração do Notion"
const cfg = $('Configuração do Notion').first().json;
const col = cfg.colunas || {};
const pad = cfg.valores_padrao || {};
const propriedade = (pr, chave) => (col[chave] ? pr[col[chave]] : undefined);
const texto = (p) => (p?.title ?? p?.rich_text ?? []).map((r) => r.plain_text).join('');
// Valor de uma coluna select/status; se estiver vazia, usa o valor padrão configurado
const opcao = (pr, chave) => {
  const p = propriedade(pr, chave);
  return p?.select?.name ?? p?.status?.name ?? p?.multi_select?.[0]?.name ?? pad[chave] ?? '';
};

const tarefas = ($('Agrupar tarefas').first().json.tarefas || [])
  .filter((t) => t.properties)
  .map((t) => {
    const pr = t.properties;
    const prazo = propriedade(pr, 'prazo')?.date;
    const fim = String(prazo?.end ?? prazo?.start ?? pad.prazo ?? '').slice(0, 10);
    return {
      titulo: texto(propriedade(pr, 'titulo')) || '(sem título)',
      url: t.url,
      status: opcao(pr, 'status'),
      urgente: !!cfg.valor_urgente && opcao(pr, 'urgencia') === cfg.valor_urgente,
      importante: !!cfg.valor_importante && opcao(pr, 'relevancia') === cfg.valor_importante,
      complexidade: opcao(pr, 'complexidade'),
      fim,
      atrasada: fim !== '' && fim < hojeISO,
    };
  })
  // Atrasadas primeiro, depois urgentes, importantes e o prazo mais próximo
  .sort((a, b) =>
    (b.atrasada - a.atrasada) ||
    (b.urgente - a.urgente) ||
    (b.importante - a.importante) ||
    (a.fim || '9999').localeCompare(b.fim || '9999'));

const linhas = [];
linhas.push(`☀️ <b>Bom dia!</b> Hoje é ${hoje.toFormat("cccc, dd 'de' LLLL")}.`);
linhas.push('');

if (clima?.main) {
  const desc = clima.weather?.[0]?.description ?? '';
  linhas.push(`🌡️ <b>Tempo em ${esc(clima.name)}:</b> ${Math.round(clima.main.temp)}°C, ${esc(desc)}`);
  linhas.push(`   mín ${Math.round(clima.main.temp_min)}°C · máx ${Math.round(clima.main.temp_max)}°C · umidade ${clima.main.humidity}%`);
} else {
  linhas.push('🌡️ Não consegui buscar a previsão do tempo hoje.');
}
linhas.push('');

linhas.push(`📅 <b>Agenda (${eventos.length})</b>`);
if (eventos.length === 0) linhas.push('   Nenhum compromisso. Dia livre!');
for (const e of eventos) {
  const hora = e.inicio ? e.inicio.toFormat('HH:mm') : 'Dia todo';
  linhas.push(`   • ${hora} — ${esc(e.titulo)}${e.local ? ` (${esc(e.local)})` : ''}`);
}
linhas.push('');

const max = cfg.max_tarefas || 15;
const dm = (iso) => DateTime.fromISO(iso).toFormat('dd/MM');
const nAtrasadas = tarefas.filter((t) => t.atrasada).length;
linhas.push(`✅ <b>Tarefas (${tarefas.length})</b>${nAtrasadas ? ` · ⚠️ ${nAtrasadas} atrasada(s)` : ''}`);
if (tarefas.length === 0) linhas.push('   Nada pendente. 🎉');
for (const t of tarefas.slice(0, max)) {
  const tags = [];
  if (t.urgente) tags.push(`🔴 ${esc(cfg.valor_urgente)}`);
  if (t.importante) tags.push(`⭐ ${esc(cfg.valor_importante)}`);
  if (t.complexidade) tags.push(`🧩 ${esc(t.complexidade)}`);
  if (t.atrasada) tags.push(`⚠️ venceu ${dm(t.fim)}`);
  else if (t.fim === hojeISO) tags.push('⏰ vence hoje');
  else if (t.fim) tags.push(`📅 até ${dm(t.fim)}`);
  const icone = t.status && t.status === cfg.status_em_andamento ? '▶️' : '•';
  linhas.push(`   ${icone} <a href="${esc(t.url)}">${esc(t.titulo)}</a>`);
  if (tags.length) linhas.push(`      ${tags.join(' · ')}`);
}
if (tarefas.length > max) linhas.push(`   … e mais ${tarefas.length - max}`);

return [{ json: { mensagem: linhas.join('\n') } }];
